package com.survivalparadise.nativegame;

import java.util.HashSet;

/** No APK is generated by this test. Exact money and source-to-bag integrity. */
public final class V143EconomyWeaponTest {
    static void ok(boolean yes,String reason){
        if(!yes)throw new AssertionError(reason);
    }
    static final class Bag implements NpcTradeLedgerV143.Inventory {
        final int[] items=new int[NpcTradeLedgerV143.ITEM_TYPES];
        final int[] slots=new int[40];
        final int[] splits=new int[40];
        Bag(){
            for(int i=0;i<39;i++)slots[i]=i;
            slots[39]=UnifiedBagSlotsV141.EMPTY;
        }
        public int available(int type){return items[type];}
        public boolean add(int type,int qty){
            if(qty<1||type==97||type>=items.length||
               qty>9999-items[type])return false;
            items[type]+=qty;
            UnifiedBagSlotsV141.sync(slots,splits,this::available);
            return true;
        }
        public boolean remove(int type,int qty){
            if(qty<1||type>=items.length||items[type]<qty)return false;
            items[type]-=qty;return true;
        }
        public boolean capacity(int type){
            return UnifiedBagSlotsV141.canStore(slots,splits,this::available,type);
        }
    }
    public static void main(String[] args){
        NutWalletV143 money=new NutWalletV143(10203);
        ok(money.coins(NutWalletV143.GOLD_COIN)==1&&
           money.coins(NutWalletV143.SILVER_COIN)==2&&
           money.coins(NutWalletV143.IRON)==3,"100:1 and 100:1 conversion");
        ok(money.debit(10000)&&money.iron()==203&&
           money.coins(NutWalletV143.SILVER_COIN)==2,"spend gold");
        ok(!money.debit(204)&&money.iron()==203,"no overdraft");
        ok(money.credit(9997)&&money.iron()==10200,"no rounding loss");
        NutWalletV143 reloaded=new NutWalletV143();
        ok(reloaded.decode(money.encode())&&reloaded.iron()==money.iron(),
            "wallet not persistent");
        ok(!reloaded.decode("-1")&&!reloaded.decode("1000000001"),
            "invalid wallet accepted");
        NpcTradeLedgerV143 ledger=new NpcTradeLedgerV143();
        NpcTradeLedgerV143.Npc trader=ledger.get("camp:5_111",0);
        ok(trader!=null&&trader.wallet.iron()>0,"NPC has no pocket budget");
        NpcTradeLedgerV143.Npc different=ledger.get("camp:6_112",3);
        ok(different!=null&&different.wallet!=trader.wallet,
            "two NPCs sharing one unlimited budget");
        Bag player=new Bag();
        int stockType=3;
        int before=trader.count(stockType);
        long price=NpcTradeLedgerV143.price(stockType);
        long walletBefore=money.iron(),traderBefore=trader.wallet.iron();
        ok(before>0&&ledger.buy(trader,stockType,1,player,money),
            "unable to buy one real NPC food item");
        ok(player.items[3]==1&&trader.count(3)==before-1&&
           money.iron()==walletBefore-price&&
           trader.wallet.iron()==traderBefore+price,
            "buy changed stock/wallet incorrectly");
        ok(UnifiedBagSlotsV141.contains(player.slots,3),
            "bought item is invisible in player's real backpack");
        long selling=NpcTradeLedgerV143.resale(stockType);
        ok(ledger.sell(trader,stockType,1,player,money),
            "unable to sell item back to real NPC");
        ok(player.items[3]==0&&trader.count(3)==before&&
           money.iron()==walletBefore-price+selling,
            "sell inflated or lost items");
        ok(!ledger.sell(trader,stockType,1,player,money),
            "player can sell item not owned");
        int count=trader.count(stockType);
        NutWalletV143 bankrupt=new NutWalletV143();
        ok(!ledger.buy(trader,stockType,1,player,bankrupt)&&
           count==trader.count(stockType),"failed trade deleted NPC stock");
        // The original 40 backpack cells cannot silently swallow new ammo.
        ok(player.add(AmmoInventoryV143.SHOTGUN,5),"ammo pouch not usable");
        ok(player.items[AmmoInventoryV143.SHOTGUN]==5&&
            UnifiedBagSlotsV141.contains(player.slots,AmmoInventoryV143.SHOTGUN),
            "shotgun shells absent from real 40-slot backpack");
        ok(!player.capacity(97),"sentinel 97 must remain empty");
        String state=ledger.encode();
        NpcTradeLedgerV143 copy=new NpcTradeLedgerV143();
        ok(copy.decode(state)&&copy.find("camp:5_111")!=null&&
           copy.find("camp:5_111").wallet.iron()==trader.wallet.iron()&&
           copy.find("camp:5_111").count(3)==trader.count(3),
            "NPC wallet or finite stock reset on reload");
        HashSet<Integer> varied=new HashSet<>();
        for(int skin=1;skin<=200;skin++){
            int gun=NpcGearV143.banditGun(skin%2,skin);
            varied.add(gun);
            int caliber=NpcGearV143.ammoType(gun);
            ok(caliber>=AmmoInventoryV143.FIRST&&
                caliber<AmmoInventoryV143.TOTAL,
                "NPC gun does not have specific compatible ammunition");
            ok(NpcGearV143.magazine(gun)>0,"NPC carried firearm has no magazine");
        }
        ok(varied.size()>=7,"bandits still only carry pistols");
        AmmoInventoryV143 ammo=new AmmoInventoryV143();
        ok(ammo.add(AmmoInventoryV143.RIFLE,30)&&
            ammo.consumeForGun(7,6)==0&&
            ammo.consumeForGun(5,10)==10&&
            ammo.count(AmmoInventoryV143.RIFLE)==20,
            "shotgun incorrectly consumed rifle ammunition");
        AmmoInventoryV143 saved=new AmmoInventoryV143();
        ok(saved.decode(ammo.encode())&&
           saved.count(AmmoInventoryV143.RIFLE)==20,
           "caliber pouch lost across save/load");
        BanditLootV87 loot=new BanditLootV87();
        BanditLootV87.Bag corpse=loot.spawnCorpse(400,500,1,2,1,1,124);
        corpse.gearManifestV141=true;
        corpse.nutsV143=10127; // 1 gold, 1 silver, 27 iron
        corpse.ammoExtraV143[AmmoInventoryV143.SHOTGUN-
            AmmoInventoryV143.FIRST]=7;
        ok(corpse.itemCount(72)==27&&corpse.itemCount(73)==1&&
           corpse.itemCount(74)==1&&corpse.itemCount(69)==7,
           "corpse not showing correct coin denominations and ammo");
        String savedCorpse=loot.encode();
        BanditLootV87 decoded=new BanditLootV87();
        decoded.decode(savedCorpse);
        ok(decoded.bags.size()==1&&decoded.bags.get(0).nutsV143==10127&&
           decoded.bags.get(0).ammoExtraV143[3]==7,
           "pocket coins or ammo disappeared on corpse save reload");
        BanditLootV87.Bag body=decoded.bags.get(0);
        ok(decoded.takeNutsV143(body,2)==1&&body.nutsV143==127,
           "gold coins looted twice or not deducted");
        ok(decoded.takeNutsV143(body,2)==0,
           "duplicate gold coin transfer");
        ok(decoded.takeAmmoV143(body,3)==7&&
           decoded.takeAmmoV143(body,3)==0,
           "duplicate recovered shotgun ammunition");
        ok(body.corpse&&body.gearManifestV141,
            "taking pocket currency erased permanent corpse/stripped state");
        System.out.println("PASS V143: real NPC stocks + wallets, 100:1 denominations, "+
            "no-loss buy/sell, 200 varied guns, six calibers, inventory, "+
            "bandit corpse nuts and ammo save/load, no duplicate looting");
    }
}
